#include <vector>
#include <algorithm>

using namespace std;

class Solution {
public:
    int kIncreasing(vector<int>& arr, int k) {
        int res = 0, n = arr.size();
        for (int i = 0; i < k; ++i) {
            vector<int> seq;
            for (int j = i; j < n; j += k)
                seq.push_back(arr[j]);
            res += seq.size() - lengthOfLNDS(seq);
        }
        return res;
    }

    int lengthOfLNDS(vector<int>& nums) {
        vector<int> sub;
        for (int x : nums) {
            auto it = upper_bound(sub.begin(), sub.end(), x);
            if (it == sub.end()) sub.push_back(x);
            else *it = x;
        }
        return sub.size();
    }
};
